/* ChartPulse Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-surface: #1a1a2e;
  --bg-card: #1E1E2E;
  --bg-card-hover: #252540;
  --bg-input: #16162B;
  --accent: #2962FF;
  --accent-hover: #2979FF;
  --accent-glow: rgba(41,98,255,0.15);
  --positive: #26A69A;
  --positive-bg: rgba(38,166,154,0.1);
  --negative: #F7525F;
  --negative-bg: rgba(247,82,95,0.1);
  --text-primary: #E0E0E0;
  --text-secondary: #9E9E9E;
  --text-muted: #6B6B80;
  --border: #2A2A3E;
  --border-light: #333352;
  --white: #FFFFFF;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --transition: 0.2s ease;
}

* { margin:0; padding:0; box-sizing:border-box; }

html { font-size:14px; scroll-behavior:smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration:none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }

img { max-width:100%; display:block; }

/* Scrollbar */
::-webkit-scrollbar { width:6px; height:6px; }
::-webkit-scrollbar-track { background:var(--bg-primary); }
::-webkit-scrollbar-thumb { background:var(--border); border-radius:3px; }
::-webkit-scrollbar-thumb:hover { background:var(--border-light); }

/* ---- NAV ---- */
.nav {
  position:sticky; top:0; z-index:100;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
  height: 56px;
  display:flex; align-items:center; justify-content:space-between;
}
.nav__logo {
  font-size:1.35rem; font-weight:800; color:var(--white);
  display:flex; align-items:center; gap:8px;
}
.nav__logo span { color:var(--accent); }
.nav__links { display:flex; gap:24px; align-items:center; }
.nav__links a {
  color:var(--text-secondary); font-size:0.9rem; font-weight:500;
  padding:6px 0; border-bottom:2px solid transparent;
  transition: all var(--transition);
}
.nav__links a:hover, .nav__links a.active {
  color:var(--white); border-bottom-color:var(--accent);
}
.nav__actions { display:flex; gap:10px; align-items:center; }

/* ---- BUTTONS ---- */
.btn {
  display:inline-flex; align-items:center; justify-content:center; gap:6px;
  padding: 8px 18px; border:none; border-radius:var(--radius-sm);
  font-family:var(--font); font-size:0.875rem; font-weight:600;
  cursor:pointer; transition:all var(--transition); white-space:nowrap;
}
.btn--primary { background:var(--accent); color:var(--white); }
.btn--primary:hover { background:var(--accent-hover); box-shadow:0 0 20px var(--accent-glow); }
.btn--outline { background:transparent; color:var(--text-primary); border:1px solid var(--border); }
.btn--outline:hover { border-color:var(--accent); color:var(--accent); }
.btn--ghost { background:transparent; color:var(--text-secondary); }
.btn--ghost:hover { color:var(--white); background:rgba(255,255,255,0.05); }
.btn--sm { padding:5px 12px; font-size:0.8rem; }
.btn--lg { padding:12px 28px; font-size:1rem; }

/* ---- TABS ---- */
.tabs {
  display:flex; gap:2px; background:var(--bg-surface);
  border-radius:var(--radius-sm); padding:3px; overflow-x:auto;
}
.tab {
  padding:7px 16px; border-radius:var(--radius-sm);
  font-size:0.8rem; font-weight:500; color:var(--text-secondary);
  cursor:pointer; white-space:nowrap; transition:all var(--transition);
  border:none; background:transparent; font-family:var(--font);
}
.tab:hover { color:var(--text-primary); }
.tab.active { background:var(--accent); color:var(--white); }

/* ---- CARDS ---- */
.card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); padding:20px;
  transition:all var(--transition);
}
.card:hover { border-color:var(--border-light); background:var(--bg-card-hover); }

/* ---- BADGES ---- */
.badge {
  display:inline-flex; align-items:center; padding:3px 8px;
  border-radius:4px; font-size:0.75rem; font-weight:600;
}
.badge--positive { background:var(--positive-bg); color:var(--positive); }
.badge--negative { background:var(--negative-bg); color:var(--negative); }
.badge--blue { background:var(--accent-glow); color:var(--accent); }
.badge--platinum { background:linear-gradient(135deg,#A8A8A8,#E8E8E8); color:#333; }
.badge--gold { background:linear-gradient(135deg,#D4A017,#FFD700); color:#333; }

/* ---- TABLES ---- */
.data-table { width:100%; border-collapse:collapse; }
.data-table th {
  text-align:left; padding:10px 12px; font-size:0.75rem;
  font-weight:600; color:var(--text-muted); text-transform:uppercase;
  letter-spacing:0.5px; border-bottom:1px solid var(--border);
}
.data-table td {
  padding:10px 12px; font-size:0.875rem; border-bottom:1px solid var(--border);
}
.data-table tr:hover td { background:rgba(255,255,255,0.02); }
.data-table .text-positive { color:var(--positive); }
.data-table .text-negative { color:var(--negative); }
.data-table .text-right { text-align:right; }

/* ---- INPUT ---- */
.input {
  background:var(--bg-input); border:1px solid var(--border);
  border-radius:var(--radius-sm); padding:8px 14px;
  color:var(--text-primary); font-family:var(--font); font-size:0.875rem;
  outline:none; transition:border-color var(--transition);
  width:100%;
}
.input:focus { border-color:var(--accent); }
.input::placeholder { color:var(--text-muted); }

/* ---- SECTION ---- */
.section { padding:40px 24px; max-width:1400px; margin:0 auto; }
.section__title {
  font-size:1.25rem; font-weight:700; color:var(--white);
  margin-bottom:20px; display:flex; align-items:center; justify-content:space-between;
}

/* ---- GRID ---- */
.grid { display:grid; gap:16px; }
.grid--2 { grid-template-columns:repeat(2,1fr); }
.grid--3 { grid-template-columns:repeat(3,1fr); }
.grid--4 { grid-template-columns:repeat(4,1fr); }
.grid--5 { grid-template-columns:repeat(5,1fr); }

/* ---- FOOTER ---- */
.footer {
  background:var(--bg-surface); border-top:1px solid var(--border);
  padding:48px 24px 24px; margin-top:60px;
}
.footer__grid {
  display:grid; grid-template-columns:repeat(auto-fit,minmax(160px,1fr));
  gap:32px; max-width:1400px; margin:0 auto;
}
.footer__col h4 {
  font-size:0.85rem; font-weight:700; color:var(--white);
  margin-bottom:12px; text-transform:uppercase; letter-spacing:0.5px;
}
.footer__col a {
  display:block; color:var(--text-secondary); font-size:0.85rem;
  padding:3px 0; transition:color var(--transition);
}
.footer__col a:hover { color:var(--accent); }
.footer__bottom {
  max-width:1400px; margin:32px auto 0; padding-top:20px;
  border-top:1px solid var(--border); display:flex;
  justify-content:space-between; align-items:center;
  font-size:0.8rem; color:var(--text-muted);
}

/* ---- UTILITIES ---- */
.text-positive { color:var(--positive) !important; }
.text-negative { color:var(--negative) !important; }
.text-accent { color:var(--accent) !important; }
.text-muted { color:var(--text-muted) !important; }
.text-secondary { color:var(--text-secondary) !important; }
.text-white { color:var(--white) !important; }
.font-mono { font-family:'SF Mono',SFMono-Regular,Consolas,'Liberation Mono',Menlo,monospace; }
.font-bold { font-weight:700; }
.font-semibold { font-weight:600; }
.text-sm { font-size:0.8rem; }
.text-xs { font-size:0.7rem; }
.text-lg { font-size:1.15rem; }
.text-xl { font-size:1.35rem; }
.text-2xl { font-size:1.75rem; }
.text-3xl { font-size:2.25rem; }
.text-4xl { font-size:3rem; }
.flex { display:flex; }
.flex-col { flex-direction:column; }
.items-center { align-items:center; }
.justify-between { justify-content:space-between; }
.justify-center { justify-content:center; }
.gap-1 { gap:4px; }
.gap-2 { gap:8px; }
.gap-3 { gap:12px; }
.gap-4 { gap:16px; }
.gap-6 { gap:24px; }
.p-4 { padding:16px; }
.p-6 { padding:24px; }
.px-4 { padding-left:16px; padding-right:16px; }
.py-2 { padding-top:8px; padding-bottom:8px; }
.mt-2 { margin-top:8px; }
.mt-4 { margin-top:16px; }
.mb-2 { margin-bottom:8px; }
.mb-4 { margin-bottom:16px; }
.mb-6 { margin-bottom:24px; }
.w-full { width:100%; }
.overflow-hidden { overflow:hidden; }
.rounded { border-radius:var(--radius-md); }
.border { border:1px solid var(--border); }
.hidden { display:none !important; }
.cursor-pointer { cursor:pointer; }
.select-none { user-select:none; }
.truncate { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }

/* ---- SPARKLINE CANVAS ---- */
.sparkline { width:80px; height:32px; }

/* ---- MARKET SUMMARY BAR ---- */
.market-bar {
  display:flex; gap:0; overflow-x:auto; background:var(--bg-surface);
  border-bottom:1px solid var(--border); padding:0 24px;
}
.market-bar__item {
  display:flex; align-items:center; gap:8px; padding:10px 20px;
  font-size:0.8rem; white-space:nowrap; border-right:1px solid var(--border);
  cursor:default;
}
.market-bar__item .name { color:var(--text-secondary); font-weight:500; }
.market-bar__item .price { color:var(--white); font-weight:600; font-family:var(--font); }
.market-bar__item .change { font-weight:600; }

/* ---- HERO ---- */
.hero {
  padding:80px 24px 60px; text-align:center;
  background:linear-gradient(180deg,var(--bg-surface) 0%,var(--bg-primary) 100%);
  position:relative; overflow:hidden;
}
.hero::before {
  content:''; position:absolute; top:-50%; left:50%; transform:translateX(-50%);
  width:800px; height:800px; background:radial-gradient(circle,var(--accent-glow) 0%,transparent 70%);
  pointer-events:none;
}
.hero__title {
  font-size:3.2rem; font-weight:800; color:var(--white);
  line-height:1.15; max-width:700px; margin:0 auto 16px;
  position:relative;
}
.hero__subtitle {
  font-size:1.1rem; color:var(--text-secondary); max-width:560px;
  margin:0 auto 32px; line-height:1.6; position:relative;
}
.hero__actions { display:flex; gap:12px; justify-content:center; position:relative; }

/* ---- WATCHLIST ---- */
.watchlist { width:260px; min-width:260px; border-right:1px solid var(--border); overflow-y:auto; height:100%; }
.watchlist__header {
  padding:12px 16px; font-size:0.85rem; font-weight:700;
  color:var(--white); border-bottom:1px solid var(--border);
  display:flex; align-items:center; justify-content:space-between;
}
.watchlist__category {
  border-bottom:1px solid var(--border);
}
.watchlist__category-header {
  padding:10px 16px; font-size:0.8rem; font-weight:600;
  color:var(--text-secondary); cursor:pointer; display:flex;
  align-items:center; justify-content:space-between;
  transition:background var(--transition);
}
.watchlist__category-header:hover { background:rgba(255,255,255,0.03); }
.watchlist__category-header .arrow {
  transition:transform var(--transition); font-size:0.7rem;
}
.watchlist__category-header.collapsed .arrow { transform:rotate(-90deg); }
.watchlist__category-body { overflow:hidden; }
.watchlist__row {
  display:grid; grid-template-columns:1fr auto auto;
  padding:8px 16px; font-size:0.8rem; cursor:pointer;
  transition:background var(--transition); gap:8px;
}
.watchlist__row:hover { background:rgba(255,255,255,0.03); }
.watchlist__row .symbol { font-weight:600; color:var(--white); }
.watchlist__row .last { font-family:var(--font); text-align:right; }
.watchlist__row .chg-pct { text-align:right; font-weight:600; }

/* ---- CHART TOOLBAR ---- */
.chart-toolbar {
  display:flex; align-items:center; gap:4px; padding:8px 16px;
  border-bottom:1px solid var(--border); background:var(--bg-surface);
  flex-wrap:wrap;
}
.chart-toolbar .symbol-info {
  display:flex; align-items:baseline; gap:8px; margin-right:16px;
}
.chart-toolbar .symbol-info .ticker { font-size:1.1rem; font-weight:700; color:var(--white); }
.chart-toolbar .symbol-info .price { font-size:1.1rem; font-weight:600; }
.chart-toolbar .tf-btn {
  padding:4px 10px; font-size:0.75rem; font-weight:500;
  border:none; background:transparent; color:var(--text-secondary);
  cursor:pointer; border-radius:3px; font-family:var(--font);
  transition:all var(--transition);
}
.chart-toolbar .tf-btn:hover { color:var(--white); background:rgba(255,255,255,0.08); }
.chart-toolbar .tf-btn.active { background:var(--accent); color:var(--white); }

/* ---- CANDLESTICK CHART ---- */
.chart-canvas-wrap {
  flex:1; position:relative; background:var(--bg-primary);
  min-height:500px;
}
.chart-canvas-wrap canvas { width:100%; height:100%; display:block; }

/* ---- DETAIL PANEL ---- */
.detail-panel {
  width:340px; min-width:340px; border-left:1px solid var(--border);
  overflow-y:auto; background:var(--bg-surface);
}
.detail-panel__header {
  padding:16px; border-bottom:1px solid var(--border);
}
.detail-panel__section {
  padding:16px; border-bottom:1px solid var(--border);
}
.detail-panel__section h3 {
  font-size:0.85rem; font-weight:700; color:var(--white);
  margin-bottom:12px; text-transform:uppercase; letter-spacing:0.5px;
}
.detail-panel__row {
  display:flex; justify-content:space-between; padding:5px 0;
  font-size:0.8rem;
}
.detail-panel__row .label { color:var(--text-secondary); }
.detail-panel__row .value { color:var(--white); font-weight:500; }

/* ---- IDEA CARD ---- */
.idea-card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); overflow:hidden;
  transition:all var(--transition);
}
.idea-card:hover { border-color:var(--border-light); transform:translateY(-2px); box-shadow:var(--shadow); }
.idea-card__img {
  width:100%; height:180px; background:var(--bg-surface);
  display:flex; align-items:center; justify-content:center;
  overflow:hidden;
}
.idea-card__img canvas { width:100%; height:100%; }
.idea-card__body { padding:16px; }
.idea-card__author {
  display:flex; align-items:center; gap:8px; margin-bottom:8px;
  font-size:0.8rem;
}
.idea-card__author .avatar {
  width:24px; height:24px; border-radius:50%;
  background:var(--accent); display:flex; align-items:center; justify-content:center;
  font-size:0.65rem; font-weight:700; color:var(--white);
}
.idea-card__title {
  font-size:0.9rem; font-weight:600; color:var(--white);
  margin-bottom:6px; line-height:1.4;
}
.idea-card__meta {
  display:flex; gap:12px; font-size:0.75rem; color:var(--text-muted);
}
.idea-card__tags { display:flex; gap:6px; margin-top:8px; flex-wrap:wrap; }
.idea-card__tag {
  padding:2px 8px; border-radius:3px; font-size:0.7rem;
  font-weight:500; background:rgba(255,255,255,0.05); color:var(--text-secondary);
}

/* ---- BROKER CARD ---- */
.broker-card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); padding:24px;
  display:grid; grid-template-columns:1fr auto; gap:16px;
  transition:all var(--transition);
}
.broker-card:hover { border-color:var(--border-light); }
.broker-card__info { display:flex; flex-direction:column; gap:8px; }
.broker-card__name { font-size:1.1rem; font-weight:700; color:var(--white); }
.broker-card__stats {
  display:flex; gap:16px; flex-wrap:wrap;
}
.broker-card__stat {
  font-size:0.8rem; color:var(--text-secondary);
}
.broker-card__stat span { color:var(--white); font-weight:600; }
.broker-card__promo {
  padding:8px 14px; background:var(--accent-glow);
  border-radius:var(--radius-sm); font-size:0.8rem;
  color:var(--accent); font-weight:600;
}
.broker-card__actions { display:flex; flex-direction:column; align-items:flex-end; justify-content:center; gap:8px; }
.broker-card__rating {
  display:flex; align-items:center; gap:6px;
}
.broker-card__rating .stars { color:#FFD700; font-size:0.9rem; }

/* ---- STATS BANNER ---- */
.stats-banner {
  background:linear-gradient(135deg,var(--accent) 0%,#1a237e 100%);
  border-radius:var(--radius-lg); padding:48px 32px;
  display:flex; justify-content:center; gap:80px; text-align:center;
}
.stats-banner__item .number {
  font-size:2.5rem; font-weight:800; color:var(--white);
}
.stats-banner__item .label {
  font-size:0.9rem; color:rgba(255,255,255,0.7); margin-top:4px;
}

/* ---- RESPONSIVE ---- */
@media (max-width:1200px) {
  .grid--4 { grid-template-columns:repeat(3,1fr); }
  .grid--5 { grid-template-columns:repeat(3,1fr); }
  .detail-panel { width:300px; min-width:300px; }
  .watchlist { width:220px; min-width:220px; }
}
@media (max-width:992px) {
  .grid--3 { grid-template-columns:repeat(2,1fr); }
  .grid--4 { grid-template-columns:repeat(2,1fr); }
  .grid--5 { grid-template-columns:repeat(2,1fr); }
  .hero__title { font-size:2.4rem; }
  .watchlist { display:none; }
  .detail-panel { width:100%; min-width:100%; border-left:none; border-top:1px solid var(--border); }
}
@media (max-width:768px) {
  .grid--2 { grid-template-columns:1fr; }
  .grid--3 { grid-template-columns:1fr; }
  .grid--4 { grid-template-columns:1fr; }
  .grid--5 { grid-template-columns:1fr; }
  .nav__links { display:none; }
  .hero__title { font-size:1.8rem; }
  .hero__subtitle { font-size:0.95rem; }
  .hero__actions { flex-direction:column; align-items:center; }
  .section { padding:24px 16px; }
  .market-bar { padding:0 12px; }
  .stats-banner { flex-direction:column; gap:24px; padding:32px 20px; }
  .broker-card { grid-template-columns:1fr; }
  .broker-card__actions { flex-direction:row; align-items:center; }
}

/* ChartPulse Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0F0F0F;
  --bg-surface: #1a1a2e;
  --bg-card: #1E1E2E;
  --bg-card-hover: #252540;
  --bg-input: #16162B;
  --accent: #2962FF;
  --accent-hover: #2979FF;
  --accent-glow: rgba(41,98,255,0.15);
  --positive: #26A69A;
  --positive-bg: rgba(38,166,154,0.1);
  --negative: #F7525F;
  --negative-bg: rgba(247,82,95,0.1);
  --text-primary: #E0E0E0;
  --text-secondary: #9E9E9E;
  --text-muted: #6B6B80;
  --border: #2A2A3E;
  --border-light: #333352;
  --white: #FFFFFF;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --transition: 0.2s ease;
}

* { margin:0; padding:0; box-sizing:border-box; }

html { font-size:14px; scroll-behavior:smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration:none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }

img { max-width:100%; display:block; }

/* Scrollbar */
::-webkit-scrollbar { width:6px; height:6px; }
::-webkit-scrollbar-track { background:var(--bg-primary); }
::-webkit-scrollbar-thumb { background:var(--border); border-radius:3px; }
::-webkit-scrollbar-thumb:hover { background:var(--border-light); }

/* ---- NAV ---- */
.nav {
  position:sticky; top:0; z-index:100;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
  height: 56px;
  display:flex; align-items:center; justify-content:space-between;
}
.nav__logo {
  font-size:1.35rem; font-weight:800; color:var(--white);
  display:flex; align-items:center; gap:8px;
}
.nav__logo span { color:var(--accent); }
.nav__links { display:flex; gap:24px; align-items:center; }
.nav__links a {
  color:var(--text-secondary); font-size:0.9rem; font-weight:500;
  padding:6px 0; border-bottom:2px solid transparent;
  transition: all var(--transition);
}
.nav__links a:hover, .nav__links a.active {
  color:var(--white); border-bottom-color:var(--accent);
}
.nav__actions { display:flex; gap:10px; align-items:center; }

/* ---- BUTTONS ---- */
.btn {
  display:inline-flex; align-items:center; justify-content:center; gap:6px;
  padding: 8px 18px; border:none; border-radius:var(--radius-sm);
  font-family:var(--font); font-size:0.875rem; font-weight:600;
  cursor:pointer; transition:all var(--transition); white-space:nowrap;
}
.btn--primary { background:var(--accent); color:var(--white); }
.btn--primary:hover { background:var(--accent-hover); box-shadow:0 0 20px var(--accent-glow); }
.btn--outline { background:transparent; color:var(--text-primary); border:1px solid var(--border); }
.btn--outline:hover { border-color:var(--accent); color:var(--accent); }
.btn--ghost { background:transparent; color:var(--text-secondary); }
.btn--ghost:hover { color:var(--white); background:rgba(255,255,255,0.05); }
.btn--sm { padding:5px 12px; font-size:0.8rem; }
.btn--lg { padding:12px 28px; font-size:1rem; }

/* ---- TABS ---- */
.tabs {
  display:flex; gap:2px; background:var(--bg-surface);
  border-radius:var(--radius-sm); padding:3px; overflow-x:auto;
}
.tab {
  padding:7px 16px; border-radius:var(--radius-sm);
  font-size:0.8rem; font-weight:500; color:var(--text-secondary);
  cursor:pointer; white-space:nowrap; transition:all var(--transition);
  border:none; background:transparent; font-family:var(--font);
}
.tab:hover { color:var(--text-primary); }
.tab.active { background:var(--accent); color:var(--white); }

/* ---- CARDS ---- */
.card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); padding:20px;
  transition:all var(--transition);
}
.card:hover { border-color:var(--border-light); background:var(--bg-card-hover); }

/* ---- BADGES ---- */
.badge {
  display:inline-flex; align-items:center; padding:3px 8px;
  border-radius:4px; font-size:0.75rem; font-weight:600;
}
.badge--positive { background:var(--positive-bg); color:var(--positive); }
.badge--negative { background:var(--negative-bg); color:var(--negative); }
.badge--blue { background:var(--accent-glow); color:var(--accent); }
.badge--platinum { background:linear-gradient(135deg,#A8A8A8,#E8E8E8); color:#333; }
.badge--gold { background:linear-gradient(135deg,#D4A017,#FFD700); color:#333; }

/* ---- TABLES ---- */
.data-table { width:100%; border-collapse:collapse; }
.data-table th {
  text-align:left; padding:10px 12px; font-size:0.75rem;
  font-weight:600; color:var(--text-muted); text-transform:uppercase;
  letter-spacing:0.5px; border-bottom:1px solid var(--border);
}
.data-table td {
  padding:10px 12px; font-size:0.875rem; border-bottom:1px solid var(--border);
}
.data-table tr:hover td { background:rgba(255,255,255,0.02); }
.data-table .text-positive { color:var(--positive); }
.data-table .text-negative { color:var(--negative); }
.data-table .text-right { text-align:right; }

/* ---- INPUT ---- */
.input {
  background:var(--bg-input); border:1px solid var(--border);
  border-radius:var(--radius-sm); padding:8px 14px;
  color:var(--text-primary); font-family:var(--font); font-size:0.875rem;
  outline:none; transition:border-color var(--transition);
  width:100%;
}
.input:focus { border-color:var(--accent); }
.input::placeholder { color:var(--text-muted); }

/* ---- SECTION ---- */
.section { padding:40px 24px; max-width:1400px; margin:0 auto; }
.section__title {
  font-size:1.25rem; font-weight:700; color:var(--white);
  margin-bottom:20px; display:flex; align-items:center; justify-content:space-between;
}

/* ---- GRID ---- */
.grid { display:grid; gap:16px; }
.grid--2 { grid-template-columns:repeat(2,1fr); }
.grid--3 { grid-template-columns:repeat(3,1fr); }
.grid--4 { grid-template-columns:repeat(4,1fr); }
.grid--5 { grid-template-columns:repeat(5,1fr); }

/* ---- FOOTER ---- */
.footer {
  background:var(--bg-surface); border-top:1px solid var(--border);
  padding:48px 24px 24px; margin-top:60px;
}
.footer__grid {
  display:grid; grid-template-columns:repeat(auto-fit,minmax(160px,1fr));
  gap:32px; max-width:1400px; margin:0 auto;
}
.footer__col h4 {
  font-size:0.85rem; font-weight:700; color:var(--white);
  margin-bottom:12px; text-transform:uppercase; letter-spacing:0.5px;
}
.footer__col a {
  display:block; color:var(--text-secondary); font-size:0.85rem;
  padding:3px 0; transition:color var(--transition);
}
.footer__col a:hover { color:var(--accent); }
.footer__bottom {
  max-width:1400px; margin:32px auto 0; padding-top:20px;
  border-top:1px solid var(--border); display:flex;
  justify-content:space-between; align-items:center;
  font-size:0.8rem; color:var(--text-muted);
}

/* ---- UTILITIES ---- */
.text-positive { color:var(--positive) !important; }
.text-negative { color:var(--negative) !important; }
.text-accent { color:var(--accent) !important; }
.text-muted { color:var(--text-muted) !important; }
.text-secondary { color:var(--text-secondary) !important; }
.text-white { color:var(--white) !important; }
.font-mono { font-family:'SF Mono',SFMono-Regular,Consolas,'Liberation Mono',Menlo,monospace; }
.font-bold { font-weight:700; }
.font-semibold { font-weight:600; }
.text-sm { font-size:0.8rem; }
.text-xs { font-size:0.7rem; }
.text-lg { font-size:1.15rem; }
.text-xl { font-size:1.35rem; }
.text-2xl { font-size:1.75rem; }
.text-3xl { font-size:2.25rem; }
.text-4xl { font-size:3rem; }
.flex { display:flex; }
.flex-col { flex-direction:column; }
.items-center { align-items:center; }
.justify-between { justify-content:space-between; }
.justify-center { justify-content:center; }
.gap-1 { gap:4px; }
.gap-2 { gap:8px; }
.gap-3 { gap:12px; }
.gap-4 { gap:16px; }
.gap-6 { gap:24px; }
.p-4 { padding:16px; }
.p-6 { padding:24px; }
.px-4 { padding-left:16px; padding-right:16px; }
.py-2 { padding-top:8px; padding-bottom:8px; }
.mt-2 { margin-top:8px; }
.mt-4 { margin-top:16px; }
.mb-2 { margin-bottom:8px; }
.mb-4 { margin-bottom:16px; }
.mb-6 { margin-bottom:24px; }
.w-full { width:100%; }
.overflow-hidden { overflow:hidden; }
.rounded { border-radius:var(--radius-md); }
.border { border:1px solid var(--border); }
.hidden { display:none !important; }
.cursor-pointer { cursor:pointer; }
.select-none { user-select:none; }
.truncate { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }

/* ---- SPARKLINE CANVAS ---- */
.sparkline { width:80px; height:32px; }

/* ---- MARKET SUMMARY BAR ---- */
.market-bar {
  display:flex; gap:0; overflow-x:auto; background:var(--bg-surface);
  border-bottom:1px solid var(--border); padding:0 24px;
}
.market-bar__item {
  display:flex; align-items:center; gap:8px; padding:10px 20px;
  font-size:0.8rem; white-space:nowrap; border-right:1px solid var(--border);
  cursor:default;
}
.market-bar__item .name { color:var(--text-secondary); font-weight:500; }
.market-bar__item .price { color:var(--white); font-weight:600; font-family:var(--font); }
.market-bar__item .change { font-weight:600; }

/* ---- HERO ---- */
.hero {
  padding:80px 24px 60px; text-align:center;
  background:linear-gradient(180deg,var(--bg-surface) 0%,var(--bg-primary) 100%);
  position:relative; overflow:hidden;
}
.hero::before {
  content:''; position:absolute; top:-50%; left:50%; transform:translateX(-50%);
  width:800px; height:800px; background:radial-gradient(circle,var(--accent-glow) 0%,transparent 70%);
  pointer-events:none;
}
.hero__title {
  font-size:3.2rem; font-weight:800; color:var(--white);
  line-height:1.15; max-width:700px; margin:0 auto 16px;
  position:relative;
}
.hero__subtitle {
  font-size:1.1rem; color:var(--text-secondary); max-width:560px;
  margin:0 auto 32px; line-height:1.6; position:relative;
}
.hero__actions { display:flex; gap:12px; justify-content:center; position:relative; }

/* ---- WATCHLIST ---- */
.watchlist { width:260px; min-width:260px; border-right:1px solid var(--border); overflow-y:auto; height:100%; }
.watchlist__header {
  padding:12px 16px; font-size:0.85rem; font-weight:700;
  color:var(--white); border-bottom:1px solid var(--border);
  display:flex; align-items:center; justify-content:space-between;
}
.watchlist__category {
  border-bottom:1px solid var(--border);
}
.watchlist__category-header {
  padding:10px 16px; font-size:0.8rem; font-weight:600;
  color:var(--text-secondary); cursor:pointer; display:flex;
  align-items:center; justify-content:space-between;
  transition:background var(--transition);
}
.watchlist__category-header:hover { background:rgba(255,255,255,0.03); }
.watchlist__category-header .arrow {
  transition:transform var(--transition); font-size:0.7rem;
}
.watchlist__category-header.collapsed .arrow { transform:rotate(-90deg); }
.watchlist__category-body { overflow:hidden; }
.watchlist__row {
  display:grid; grid-template-columns:1fr auto auto;
  padding:8px 16px; font-size:0.8rem; cursor:pointer;
  transition:background var(--transition); gap:8px;
}
.watchlist__row:hover { background:rgba(255,255,255,0.03); }
.watchlist__row .symbol { font-weight:600; color:var(--white); }
.watchlist__row .last { font-family:var(--font); text-align:right; }
.watchlist__row .chg-pct { text-align:right; font-weight:600; }

/* ---- CHART TOOLBAR ---- */
.chart-toolbar {
  display:flex; align-items:center; gap:4px; padding:8px 16px;
  border-bottom:1px solid var(--border); background:var(--bg-surface);
  flex-wrap:wrap;
}
.chart-toolbar .symbol-info {
  display:flex; align-items:baseline; gap:8px; margin-right:16px;
}
.chart-toolbar .symbol-info .ticker { font-size:1.1rem; font-weight:700; color:var(--white); }
.chart-toolbar .symbol-info .price { font-size:1.1rem; font-weight:600; }
.chart-toolbar .tf-btn {
  padding:4px 10px; font-size:0.75rem; font-weight:500;
  border:none; background:transparent; color:var(--text-secondary);
  cursor:pointer; border-radius:3px; font-family:var(--font);
  transition:all var(--transition);
}
.chart-toolbar .tf-btn:hover { color:var(--white); background:rgba(255,255,255,0.08); }
.chart-toolbar .tf-btn.active { background:var(--accent); color:var(--white); }

/* ---- CANDLESTICK CHART ---- */
.chart-canvas-wrap {
  flex:1; position:relative; background:var(--bg-primary);
  min-height:500px;
}
.chart-canvas-wrap canvas { width:100%; height:100%; display:block; }

/* ---- DETAIL PANEL ---- */
.detail-panel {
  width:340px; min-width:340px; border-left:1px solid var(--border);
  overflow-y:auto; background:var(--bg-surface);
}
.detail-panel__header {
  padding:16px; border-bottom:1px solid var(--border);
}
.detail-panel__section {
  padding:16px; border-bottom:1px solid var(--border);
}
.detail-panel__section h3 {
  font-size:0.85rem; font-weight:700; color:var(--white);
  margin-bottom:12px; text-transform:uppercase; letter-spacing:0.5px;
}
.detail-panel__row {
  display:flex; justify-content:space-between; padding:5px 0;
  font-size:0.8rem;
}
.detail-panel__row .label { color:var(--text-secondary); }
.detail-panel__row .value { color:var(--white); font-weight:500; }

/* ---- IDEA CARD ---- */
.idea-card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); overflow:hidden;
  transition:all var(--transition);
}
.idea-card:hover { border-color:var(--border-light); transform:translateY(-2px); box-shadow:var(--shadow); }
.idea-card__img {
  width:100%; height:180px; background:var(--bg-surface);
  display:flex; align-items:center; justify-content:center;
  overflow:hidden;
}
.idea-card__img canvas { width:100%; height:100%; }
.idea-card__body { padding:16px; }
.idea-card__author {
  display:flex; align-items:center; gap:8px; margin-bottom:8px;
  font-size:0.8rem;
}
.idea-card__author .avatar {
  width:24px; height:24px; border-radius:50%;
  background:var(--accent); display:flex; align-items:center; justify-content:center;
  font-size:0.65rem; font-weight:700; color:var(--white);
}
.idea-card__title {
  font-size:0.9rem; font-weight:600; color:var(--white);
  margin-bottom:6px; line-height:1.4;
}
.idea-card__meta {
  display:flex; gap:12px; font-size:0.75rem; color:var(--text-muted);
}
.idea-card__tags { display:flex; gap:6px; margin-top:8px; flex-wrap:wrap; }
.idea-card__tag {
  padding:2px 8px; border-radius:3px; font-size:0.7rem;
  font-weight:500; background:rgba(255,255,255,0.05); color:var(--text-secondary);
}

/* ---- BROKER CARD ---- */
.broker-card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); padding:24px;
  display:grid; grid-template-columns:1fr auto; gap:16px;
  transition:all var(--transition);
}
.broker-card:hover { border-color:var(--border-light); }
.broker-card__info { display:flex; flex-direction:column; gap:8px; }
.broker-card__name { font-size:1.1rem; font-weight:700; color:var(--white); }
.broker-card__stats {
  display:flex; gap:16px; flex-wrap:wrap;
}
.broker-card__stat {
  font-size:0.8rem; color:var(--text-secondary);
}
.broker-card__stat span { color:var(--white); font-weight:600; }
.broker-card__promo {
  padding:8px 14px; background:var(--accent-glow);
  border-radius:var(--radius-sm); font-size:0.8rem;
  color:var(--accent); font-weight:600;
}
.broker-card__actions { display:flex; flex-direction:column; align-items:flex-end; justify-content:center; gap:8px; }
.broker-card__rating {
  display:flex; align-items:center; gap:6px;
}
.broker-card__rating .stars { color:#FFD700; font-size:0.9rem; }

/* ---- STATS BANNER ---- */
.stats-banner {
  background:linear-gradient(135deg,var(--accent) 0%,#1a237e 100%);
  border-radius:var(--radius-lg); padding:48px 32px;
  display:flex; justify-content:center; gap:80px; text-align:center;
}
.stats-banner__item .number {
  font-size:2.5rem; font-weight:800; color:var(--white);
}
.stats-banner__item .label {
  font-size:0.9rem; color:rgba(255,255,255,0.7); margin-top:4px;
}

/* ---- RESPONSIVE ---- */
@media (max-width:1200px) {
  .grid--4 { grid-template-columns:repeat(3,1fr); }
  .grid--5 { grid-template-columns:repeat(3,1fr); }
  .detail-panel { width:300px; min-width:300px; }
  .watchlist { width:220px; min-width:220px; }
}
@media (max-width:992px) {
  .grid--3 { grid-template-columns:repeat(2,1fr); }
  .grid--4 { grid-template-columns:repeat(2,1fr); }
  .grid--5 { grid-template-columns:repeat(2,1fr); }
  .hero__title { font-size:2.4rem; }
  .watchlist { display:none; }
  .detail-panel { width:100%; min-width:100%; border-left:none; border-top:1px solid var(--border); }
}
@media (max-width:768px) {
  .grid--2 { grid-template-columns:1fr; }
  .grid--3 { grid-template-columns:1fr; }
  .grid--4 { grid-template-columns:1fr; }
  .grid--5 { grid-template-columns:1fr; }
  .nav__links { display:none; }
  .hero__title { font-size:1.8rem; }
  .hero__subtitle { font-size:0.95rem; }
  .hero__actions { flex-direction:column; align-items:center; }
  .section { padding:24px 16px; }
  .market-bar { padding:0 12px; }
  .stats-banner { flex-direction:column; gap:24px; padding:32px 20px; }
  .broker-card { grid-template-columns:1fr; }
  .broker-card__actions { flex-direction:row; align-items:center; }
}

