// WATCHLIST ACCORDION
// =============================================
const catHeaders = document.querySelectorAll('.watchlist__category-header');
catHeaders.forEach(function(header) {
  header.addEventListener('click', function() {
    const cat = this.getAttribute('data-category');
    const body = document.getElementById('cat-' + cat);
    const isCollapsed = this.classList.contains('collapsed');
    if (isCollapsed) {
      this.classList.remove('collapsed');
      body.style.display = '';
    } else {
      this.classList.add('collapsed');
      body.style.display = 'none';
    }
  });
});

// =============================================
// TIMEFRAME TOGGLE
// =============================================
const tfBtns = document.querySelectorAll('.tf-btn');
tfBtns.forEach(function(btn) {
  btn.addEventListener('click', function() {
    tfBtns.forEach(function(b) { b.classList.remove('active'); });
    this.classList.add('active');
    drawChart();
  });
});

